package com.companages.service;
import com.companages.dto.*; import com.companages.entity.*;
final class Mappers { private Mappers(){} static AuthDtos.UserResponse user(User u){return new AuthDtos.UserResponse(u.getId(),u.getName(),u.getEmail(),u.getCreatedAt());} static OrganizationDtos.Response organization(Organization o){return new OrganizationDtos.Response(o.getId(),o.getName(),o.getDescription(),o.getCreatedAt(),o.getUpdatedAt());} static MemberDtos.Response member(Member m){return new MemberDtos.Response(m.getId(),m.getName(),m.getEmail(),m.getOrganization().getId(),m.getCreatedAt(),m.getUpdatedAt());} static PositionDtos.Response position(Position p){return new PositionDtos.Response(p.getId(),p.getName(),p.getDescription(),p.getOrganization().getId(),p.getCreatedAt(),p.getUpdatedAt());} static AssignmentDtos.Response assignment(Assignment a){return new AssignmentDtos.Response(a.getId(),a.getOrganization().getId(),member(a.getMember()),position(a.getPosition()),a.getCreatedAt());} }
